import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);
const files = {"dist/app.js":"","dist/assets/brand-lockup.png":"","dist/assets/brand-mark.png":"","dist/assets/hero-city.jpg":"","dist/data/municipality-official-services.json":"","dist/index.html":"","dist/manifest.webmanifest":"","dist/styles.css":"","netlify/functions/analyze.mjs":"","netlify/functions/health.mjs":"","netlify/functions/lib/analysis-core.mjs":"","netlify/functions/lib/environment-client.mjs":"","netlify/functions/lib/geo.mjs":"","netlify/functions/lib/http.mjs":"","netlify/functions/lib/municipality-catalog.mjs":"","netlify/functions/lib/municipality-provider.mjs":"","netlify/functions/lib/open-official-source-client.mjs":"","netlify/functions/lib/plan-ai-client.mjs":"","netlify/functions/lib/plan-context-client.mjs":"","netlify/functions/lib/plan-record-client.mjs":"","netlify/functions/lib/tkgm-api.mjs":"","netlify/functions/lib/tkgm-client.mjs":"","netlify/functions/lib/zoning-client.mjs":"","netlify/functions/lib/zoning-document-parser.mjs":"","netlify/functions/official-services.mjs":"","netlify/functions/open-source-scan.mjs":"","netlify/functions/parse-zoning-document.mjs":"","netlify/functions/plan-ai.mjs":"","netlify/functions/plan-records.mjs":"","netlify/functions/request-analysis.mjs":"","netlify/functions/tkgm.mjs":"","netlify/functions/user-data.mjs":"","netlify.toml":""};

await rm('dist', { recursive: true, force: true });
await rm('netlify/functions', { recursive: true, force: true });

for (const [path, encoded] of Object.entries(files)) {
  await mkdir(dirname(path), { recursive: true });
  await writeFile(path, Buffer.from(encoded, 'base64'));
}

const syntaxChecks = ["dist/app.js", "netlify/functions/analyze.mjs", "netlify/functions/health.mjs", "netlify/functions/lib/analysis-core.mjs", "netlify/functions/lib/environment-client.mjs", "netlify/functions/lib/geo.mjs", "netlify/functions/lib/http.mjs", "netlify/functions/lib/municipality-catalog.mjs", "netlify/functions/lib/municipality-provider.mjs", "netlify/functions/lib/open-official-source-client.mjs", "netlify/functions/lib/plan-ai-client.mjs", "netlify/functions/lib/plan-context-client.mjs", "netlify/functions/lib/plan-record-client.mjs", "netlify/functions/lib/tkgm-api.mjs", "netlify/functions/lib/tkgm-client.mjs", "netlify/functions/lib/zoning-client.mjs", "netlify/functions/lib/zoning-document-parser.mjs", "netlify/functions/official-services.mjs", "netlify/functions/open-source-scan.mjs", "netlify/functions/parse-zoning-document.mjs", "netlify/functions/plan-ai.mjs", "netlify/functions/plan-records.mjs", "netlify/functions/request-analysis.mjs", "netlify/functions/tkgm.mjs", "netlify/functions/user-data.mjs"];
for (const path of syntaxChecks) await execFileAsync(process.execPath, ['--check', path]);

const [html, app, styles, health, openSourceScanApi, openSourceClient, zoningClient, analysisCore, environmentClient, documentApi, documentParser, planRecords, planAiApi, planAiClient, catalogJson, netlifyConfig] = await Promise.all([
  readFile('dist/index.html', 'utf8'),
  readFile('dist/app.js', 'utf8'),
  readFile('dist/styles.css', 'utf8'),
  readFile('netlify/functions/health.mjs', 'utf8'),
  readFile('netlify/functions/open-source-scan.mjs', 'utf8'),
  readFile('netlify/functions/lib/open-official-source-client.mjs', 'utf8'),
  readFile('netlify/functions/lib/zoning-client.mjs', 'utf8'),
  readFile('netlify/functions/lib/analysis-core.mjs', 'utf8'),
  readFile('netlify/functions/lib/environment-client.mjs', 'utf8'),
  readFile('netlify/functions/parse-zoning-document.mjs', 'utf8'),
  readFile('netlify/functions/lib/zoning-document-parser.mjs', 'utf8'),
  readFile('netlify/functions/lib/plan-record-client.mjs', 'utf8'),
  readFile('netlify/functions/plan-ai.mjs', 'utf8'),
  readFile('netlify/functions/lib/plan-ai-client.mjs', 'utf8'),
  readFile('dist/data/municipality-official-services.json', 'utf8'),
  readFile('netlify.toml', 'utf8')
]);
const catalog = JSON.parse(catalogJson);
if (catalog?.stats?.recordCount !== 117) throw new Error('Gömülü belediye kataloğu 117 kayıt içermiyor.');
if (!catalog.records?.some((item) => item.authority === 'Şişli Belediyesi')) throw new Error('Şişli Belediyesi katalog kaydı eksik.');
if (!catalog.records?.some((item) => item.authority === 'Pendik Belediyesi')) throw new Error('Pendik Belediyesi katalog kaydı eksik.');

const combined = [html, app, styles, health, openSourceScanApi, openSourceClient, zoningClient, analysisCore, environmentClient, documentApi, documentParser, planRecords, planAiApi, planAiClient, netlifyConfig].join('\n');
const requiredMarkers = [
  'planlamasyon-theme-v3-2-0',
  'planlamasyon-netlify-v3.2.0',
  'sourceScanCard', 'renderSourceScan', '/api/open-source-scan',
  'OPEN_OFFICIAL_SOURCE_VERSION', 'discoverOpenOfficialZoning', 'trk_eplan_kesinlesmis_uip_wms',
  'eDevletFreeSourcePriority', 'documentUploadFallbackOnly', 'Son Çare: Resmî Belge Ekle',
  'officialZoningDocumentReader', '/api/parse-zoning-document', 'parcelDocumentMatchGuard',
  'planRecordsCard', '/api/plan-records', '/api/official-services', '/api/analyze',
  'PLAN_AI_MODEL', 'stepfun-ai/step-3.7-flash', '/api/plan-ai', 'NVIDIA_API_KEY',
  'ai-assisted-official', 'Plan AI · Açık resmî kaynak okuması', 'planAiCard', 'openPlanAiDrawer',
  'pdfjs-dist@6.2.108', 'tesseract.js@6', 'unpdf', 'Nominatim', 'embeddedPublicPlanRecords'
];
for (const marker of requiredMarkers) if (!combined.includes(marker)) throw new Error(`Eksik v3.2 build işareti: ${marker}`);
if (/Bilgi 1|Bilgi 2|loadingRows/.test(app + html)) throw new Error('Eski sahte yükleme satırları temizlenmedi.');
if (app.includes('0 / 0')) throw new Error('Eksik TAKS/Emsal 0 / 0 gösteriliyor.');
if (combined.includes('prefers-color-scheme')) throw new Error('Tema cihaz temasına bağlı olmamalıdır.');
if (!netlifyConfig.includes('from = "/api/plan-ai"')) throw new Error('Plan AI API yönlendirmesi eksik.');
if (!netlifyConfig.includes('from = "/api/open-source-scan"')) throw new Error('Açık kaynak tarama API yönlendirmesi eksik.');
if (!netlifyConfig.includes('from = "/api/parse-zoning-document"')) throw new Error('Belge okuma API yönlendirmesi eksik.');

console.log(`Planlamasyon v3.2 build tamamlandı: ${Object.keys(files).length - 1} çalışma dosyası, ${catalog.stats.recordCount} belediye bağlantısı ve NVIDIA Plan AI üretildi.`);
